// Offline cache for Jamyang Dzongsar Construction. Generated by build.py; do not edit.
const CACHE = 'sitebook-6782a3ca49';
const FILES = ["./", "index.html", "manifest.webmanifest", "fonts.css", "Barlow-400.woff2", "Barlow-500.woff2", "Barlow-600.woff2", "Barlow-700.woff2", "BarlowCondensed-600.woff2", "BarlowCondensed-700.woff2", "BarlowCondensed-800.woff2", "icon-180.png", "icon-192.png", "icon-512.png"];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});

// App files: answer from the cache first so it opens instantly with no network,
// then refresh the cached copy in the background when online.
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  e.respondWith(caches.match(e.request, { ignoreSearch: true }).then(hit => {
    const net = fetch(e.request).then(res => {
      if (res.ok && new URL(e.request.url).origin === location.origin) {
        const copy = res.clone();
        caches.open(CACHE).then(c => c.put(e.request, copy));
      }
      return res;
    }).catch(() => hit || caches.match('index.html'));
    return hit || net;
  }));
});
